import{GYM5_WARPS}from'../gym5_authority_candidate/fixed-warp-registration.mjs';import{cellPosition}from'../../../world/definition.mjs';export const GYM='world:gym:5';export{GYM5_WARPS};export const inGymWarp=(r,f)=>r.approach.rows.some(([y,a,b])=>f[1]===y&&f[0]>=a&&f[0]<b);export function validGymOrigin(id,runtime,definition){const r=GYM5_WARPS.find(q=>q.pointId===id),last=runtime.world.routeLog.at(-1);if(!r||JSON.stringify(definition.points[id])!==JSON.stringify(r.sourceRow)||last?.warpId!==id||last.from!==r.mapId||last.to!==r.sourceRow.targetMapId)return false;const p=cellPosition(r.sourceRow.targetMapId,...r.sourceRow.target);return runtime.position.scene===p.scene&&runtime.position.x===p.x&&runtime.position.y===p.y}export class GymWarpGuard{#released=false;#left=new Set;reset(){this.#released=false;this.#left.clear()}release(){this.#released=true}observe(map,foot){for(const r of GYM5_WARPS)if(r.mapId===map&&!inGymWarp(r,foot))this.#left.add(r.pointId)}readiness(r){return!this.#left.has(r.pointId)?'LEAVE_REQUIRED':!this.#released?'RELEASE_REQUIRED':'READY'}can(r){return this.readiness(r)==='READY'}press(r){if(!this.can(r))return false;this.#released=false;return true}}
